using System.Security.Claims;
using Microsoft.EntityFrameworkCore;
namespace Decont;
public class Reports(Db db,Posting? posting=null){
 public Task<Dictionary<string,string>> Names()=>db.Users.ToDictionaryAsync(u=>u.Id,u=>u.Name);
 public static string Actor(ClaimsPrincipal u)=>u.FindFirstValue(ClaimTypes.NameIdentifier)??throw new DomainException("unauthorized","Autentificare necesară.","Authentication required.",401);
 public void Log(ClaimsPrincipal u,Guid? report,string entity,string action,object? before=null,object? after=null,string? reason=null)=>db.Audits.Add(new(){Actor=Actor(u),ReportId=report,Entity=entity,Action=action,Before=before==null?null:Serialization.Write(before),After=after==null?null:Serialization.Write(after),Reason=reason});
 public IQueryable<Report> Scope(ClaimsPrincipal u){var id=Actor(u);if(u.IsInRole("Finance")||u.IsInRole("Admin")||u.IsInRole("Auditor"))return db.Reports;var employee=u.IsInRole("Employee");var manager=u.IsInRole("Manager");var today=DateOnly.FromDateTime(DateTime.UtcNow);return db.Reports.Where(r=>(employee&&r.EmployeeId==id)||(manager&&r.State!=States.Draft&&(r.ManagerId==id||db.Delegations.Any(d=>d.ManagerId==r.ManagerId&&d.DelegateId==id&&d.From<=today&&d.To>=today))));}
 public async Task<Report> Get(Guid id,ClaimsPrincipal u)=>await Scope(u).Include(r=>r.Attachments).Include(r=>r.Lines).ThenInclude(l=>l.Evidence).SingleOrDefaultAsync(r=>r.Id==id)??throw new DomainException("not_found","Decontul nu există.","Report not found.",404);
 public async Task<Report> Version(Guid id,long version,ClaimsPrincipal u){var r=await Get(id,u);Guard.Require(r.Version==version,"conflict","Datele au fost modificate. Reîncarcă.","Data changed. Reload.",409);return r;}
 public static void Touch(Report r){r.Version++;r.Updated=DateTime.UtcNow;}
 public void Edit(Report r,ClaimsPrincipal u,string? reason){if(u.IsInRole("Employee")&&r.EmployeeId==Actor(u)&&States.EmployeeEdit(r.State))return;Guard.Require(u.IsInRole("Finance")&&States.FinanceEdit(r.State),"forbidden","Nu poți modifica acest decont.","You cannot edit this report.",403);Guard.Reason(reason);if(r.State==States.Ready){r.State=States.Finance;Log(u,r.Id,"Report","FinanceReviewInvalidated",States.Ready,States.Finance,reason);}}
 public async Task<Report> Create(ClaimsPrincipal u,string purpose){Guard.Require(u.IsInRole("Employee"),"forbidden","Rolul Employee este necesar.","Employee role required.",403);var user=await db.Users.SingleAsync(x=>x.Id==Actor(u));var day=DateOnly.FromDateTime(DateTime.UtcNow);var assignment=await db.Assignments.SingleOrDefaultAsync(a=>a.UserId==user.Id&&a.From<=day&&(a.To==null||a.To>=day));var r=new Report{EmployeeId=user.Id,ManagerId=assignment?.ManagerId??user.ManagerId??"",Purpose=purpose.Trim()};db.Reports.Add(r);Log(u,r.Id,"Report","Created",after:new{r.Number,r.Purpose});return r;}
 public async Task Apply(Line l,ExpenseData input){var siblings=await db.Lines.Where(x=>x.ReportId==l.ReportId&&x.Id!=l.Id&&!x.Archived).ToListAsync();Guard.Require(siblings.All(x=>x.Data().Payment==input.Payment),"mixed_payment","Folosește deconturi separate pentru plata personală și cardul companiei.","Use separate reports for personal payments and company-card expenses.");Guard.Require(input.Supplier.Length<=256&&input.Invoice.Length<=128&&input.Description.Length<=1000,"length","Textul depășește limita permisă.","Text exceeds the permitted length.");Guard.Require(input.Amount>0,"amount","Suma trebuie să fie pozitivă.","Amount must be positive.");Guard.Require(DateOnly.TryParse(input.Date,out var date),"date","Data nu este validă.","Invalid date.");Guard.Require(!await db.Matches.AnyAsync(m=>m.LineId==l.Id),"matched","Anulează asocierea înainte de modificare.","Undo the match before editing.");var applicable=Rules.DomesticVat(input);var d=input with{Cui=applicable?Rules.Cui(input.Cui):null,Taxes=applicable?input.Taxes:[],HasCompanyCui=input.Country=="RO"?input.HasCompanyCui:false,Amount=Rules.Money(input.Amount)};if(applicable){var suppliers=await db.Masters.Where(m=>m.Kind=="suppliers"&&m.Code==Rules.Cui(d.Cui)).ToListAsync();var found=suppliers.SingleOrDefault(m=>Rules.Effective(m,date));if(found!=null)d=d with{Supplier=found.NameRo};}l.Json=Serialization.Write(d);l.DuplicateDisposition=null;l.VatOverrideReason=null;
  if(d.Currency=="RON"){l.EstimatedRon=d.Amount;l.FxVersion=null;}else{var rates=await db.Masters.Where(m=>m.Kind=="fx"&&m.Code==d.Currency).ToListAsync();var rate=rates.SingleOrDefault(m=>Rules.Effective(m,date));Guard.Require(rate!=null&&Rules.Number(rate,"ronRate")>0,"fx","Configurează cursul intern pentru dată și monedă.","Configure an internal FX rate for this date and currency.");l.EstimatedRon=Rules.Money(d.Amount*Rules.Number(rate!,"ronRate"));l.FxVersion=rate!.Id.ToString();}
 }
 public void Snapshot(Report r,ClaimsPrincipal u){r.Revision++;var json=Serialization.Write(new{r.Id,r.Number,r.EmployeeId,r.ManagerId,r.Purpose,r.Revision,Attachments=r.Attachments.Where(e=>!e.Archived).Select(e=>new{e.Id,e.Hash,e.Name,e.CoveredLines}),Lines=r.Lines.Where(l=>!l.Archived).Select(l=>new{l.Id,l.Json,l.EstimatedRon,l.SettledRon,l.FxVersion,Evidence=l.Evidence.Where(e=>!e.Archived).Select(e=>new{e.Id,e.Hash,e.Name})})});db.Snapshots.Add(new(){ReportId=r.Id,Revision=r.Revision,Json=json,Hash=Serialization.Hash(json),Actor=Actor(u)});}
 public async Task<List<Problem>> Validate(Report r,bool erp=false){var problems=Rules.Validate(r,await db.Masters.ToListAsync(),erp,await db.SupplierAccounts.ToListAsync());var otherLines=await db.Lines.Where(l=>!l.Archived).ToListAsync();var hashes=(await db.Evidence.Where(e=>!e.Archived).ToListAsync()).GroupBy(e=>e.Hash).ToDictionary(g=>g.Key,g=>g.Select(e=>e.LineId).ToList());var otherBundles=await db.ReportAttachments.Where(e=>!e.Archived&&e.ReportId!=r.Id).ToListAsync();foreach(var l in r.Lines.Where(l=>!l.Archived&&l.DuplicateDisposition==null)){var d=l.Data();var exact=otherLines.Where(x=>x.Id!=l.Id).Any(x=>{var o=x.Data();return !string.IsNullOrWhiteSpace(d.Invoice)&&Rules.Cui(d.Cui)!=""&&Rules.Cui(o.Cui)==Rules.Cui(d.Cui)&&o.Invoice==d.Invoice;})||l.Evidence.Any(e=>!e.Archived&&hashes.GetValueOrDefault(e.Hash)?.Any(id=>id!=l.Id)==true);exact=exact||l.Evidence.Any(e=>!e.Archived&&otherBundles.Any(b=>b.Hash==e.Hash))||r.Attachments.Where(e=>!e.Archived&&e.Covers(l.Id)).Any(e=>otherBundles.Any(b=>b.Hash==e.Hash)||otherLines.Where(x=>x.ReportId!=r.Id).Any(x=>hashes.GetValueOrDefault(e.Hash)?.Contains(x.Id)==true));if(exact)problems.Add(new("duplicate_exact","Document duplicat. Finance trebuie să decidă.","Duplicate document. Finance must resolve it.",l.Id,erp));else if(otherLines.Where(x=>x.Id!=l.Id).Any(x=>{var o=x.Data();return !string.IsNullOrWhiteSpace(d.Supplier)&&o.Supplier.Equals(d.Supplier,StringComparison.OrdinalIgnoreCase)&&o.Amount==d.Amount&&o.Currency==d.Currency&&o.Date==d.Date;}))problems.Add(new("duplicate_probable","Posibil duplicat. Necesită verificare.","Possible duplicate. Review required.",l.Id,erp));}return problems;}
 public async Task Notify(Report r,string userId,string action){var(inApp,email)=await NotificationPolicies.Channels(db,action);if(inApp)db.Notices.Add(new(){UserId=userId,ReportId=r.Id,Event=action});var user=await db.Users.FindAsync(userId);if(email&&!string.IsNullOrEmpty(user?.Email))db.Jobs.Add(new(){Kind="Email",Json=Serialization.Write(new{to=user.Email,reportId=r.Id,userId,action,subject=$"Decont {r.Number}: {action}",text=$"Decont {r.Number} — {r.Purpose}\n{action}"})});if(!inApp&&action.StartsWith("Reminder:")||!inApp&&action.StartsWith("Escalation:"))db.Notices.Add(new(){UserId=userId,ReportId=r.Id,Event=action,Read=true,Hidden=true});}
 public async Task Submit(Report r,ClaimsPrincipal u){Guard.Require(r.EmployeeId==Actor(u)&&u.IsInRole("Employee")&&States.EmployeeEdit(r.State),"forbidden","Decontul nu poate fi trimis.","Cannot submit this report.",403);var issues=await Validate(r);Guard.Require(!issues.Any(p=>p.Blocking),"validation",Serialization.Write(issues),Serialization.Write(issues));var manager=await db.Users.FindAsync(r.ManagerId);Guard.Require(manager!=null&&manager.Active&&r.ManagerId!=r.EmployeeId,"manager","Managerul trebuie să fie activ și diferit de angajat.","Manager must be active and different from employee.");Guard.Require(await db.UserRoles.Join(db.Roles,x=>x.RoleId,y=>y.Id,(x,y)=>new{x.UserId,y.Name}).AnyAsync(x=>x.UserId==r.ManagerId&&x.Name=="Manager"),"manager","Managerul nu are rolul necesar.","Assigned manager lacks the Manager role.");Snapshot(r,u);r.State=States.Manager;Touch(r);Log(u,r.Id,"Report","Submitted",after:new{r.State,r.Revision});await Notify(r,r.ManagerId,"Submitted");var masters=await db.Masters.ToListAsync();foreach(var l in r.Lines.Where(l=>!l.Archived)){var d=l.Data();if(!Rules.DomesticVat(d))continue;var supplier=masters.SingleOrDefault(m=>m.Kind=="suppliers"&&m.Code==Rules.Cui(d.Cui)&&Rules.Effective(m,DateOnly.Parse(d.Date)));if((supplier==null||Rules.Text(supplier,"vendorAccount")==""&&!await db.SupplierAccounts.AnyAsync(a=>a.Cui==Rules.Cui(d.Cui)&&a.From<=DateOnly.Parse(d.Date)&&(a.To==null||a.To>=DateOnly.Parse(d.Date))))&&!db.Vendors.Local.Any(v=>v.ReportId==r.Id&&v.Cui==Rules.Cui(d.Cui))&&!await db.Vendors.AnyAsync(v=>v.ReportId==r.Id&&v.Cui==Rules.Cui(d.Cui))){db.Vendors.Add(new(){ReportId=r.Id,Cui=Rules.Cui(d.Cui),Supplier=d.Supplier});var finances=await db.UserRoles.Join(db.Roles,x=>x.RoleId,y=>y.Id,(x,y)=>new{x.UserId,y.Name}).Where(x=>x.Name=="Finance").Select(x=>x.UserId).ToListAsync();foreach(var finance in finances)await Notify(r,finance,"VendorRequired");}}}
 public async Task<bool> Manager(Report r,ClaimsPrincipal u){var id=Actor(u);var day=DateOnly.FromDateTime(DateTime.UtcNow);return u.IsInRole("Manager")&&r.EmployeeId!=id&&(r.ManagerId==id||await db.Delegations.AnyAsync(d=>d.ManagerId==r.ManagerId&&d.DelegateId==id&&d.From<=day&&d.To>=day));}
 public async Task Action(Report r,ClaimsPrincipal u,string action,string? reason){var before=r.State;if(action is "approve" or "reject"){Guard.Require(await Manager(r,u)&&r.State is States.Manager or States.Reapproval,"forbidden","Nu poți decide această aprobare.","Cannot decide this approval.",403);if(action=="approve"){var issues=await Validate(r);Guard.Require(!issues.Any(p=>p.Blocking),"validation",Serialization.Write(issues),Serialization.Write(issues));}if(action=="reject")Guard.Reason(reason);db.Decisions.Add(new(){ReportId=r.Id,Revision=r.Revision,Actor=Actor(u),Action=action,Reason=reason,RevisionHash=(await db.Snapshots.SingleAsync(s=>s.ReportId==r.Id&&s.Revision==r.Revision)).Hash});r.State=action=="approve"?States.Finance:States.Rejected;if(action=="approve")r.ApprovedPersonal=Rules.Personal(r);await Notify(r,r.EmployeeId,action);}else{Guard.Require(u.IsInRole("Finance"),"forbidden","Rolul Finance este necesar.","Finance role required.",403);if(action=="close"){Guard.Require(r.State==States.Posted,"state","Decontul nu este postat.","Report is not posted.");r.State=States.Closed;}else if(action=="return"){Guard.Require(States.FinanceEdit(r.State),"state","Decontul nu este în verificare.","Report is not in review.");Guard.Reason(reason);r.State=States.Returned;await Notify(r,r.EmployeeId,"Returned");}else if(action=="complete"){Guard.Require(States.FinanceEdit(r.State),"state","Decontul nu este în verificare.","Report is not in review.");var issues=await Validate(r,true);Guard.Require(await db.Decisions.AnyAsync(d=>d.ReportId==r.Id&&d.Revision==r.Revision&&d.Action=="approve"),"approval","Lipsește aprobarea curentă.","Current approval missing.");Guard.Require(!issues.Any(p=>p.Blocking),"preflight",Serialization.Write(issues),Serialization.Write(issues));(posting??new Posting()).Build(r,await db.Users.SingleAsync(x=>x.Id==r.EmployeeId),await db.Masters.ToListAsync(),await db.SupplierAccounts.ToListAsync());db.Reviews.Add(new(){ReportId=r.Id,Revision=r.Revision,Actor=Actor(u),Checks=Serialization.Write(issues)});r.State=States.Ready;await Notify(r,r.EmployeeId,"ERPReady");}else throw new DomainException("action","Acțiunea nu este validă.","Invalid action.");}Touch(r);Log(u,r.Id,"Report",action,before,new{r.State,r.Revision},reason);}
 public async Task Reapproval(Report r,ClaimsPrincipal u){if(u.IsInRole("Finance")&&States.FinanceEdit(r.State)&&Rules.Personal(r)>r.ApprovedPersonal){var policies=await db.Masters.Where(m=>m.Kind=="policies"&&m.Code=="workflow").ToListAsync();var policy=policies.FirstOrDefault(m=>Rules.Effective(m,DateOnly.FromDateTime(DateTime.UtcNow)));if(policy!=null&&Rules.Data(policy).TryGetProperty("requireReapprovalOnPersonalIncrease",out var flag)&&!flag.GetBoolean())return;Snapshot(r,u);r.State=States.Reapproval;await Notify(r,r.ManagerId,"ReapprovalRequired");}}
}
